def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Fraud_Reports_by_Payment_Method.csv"
    return pd.read_csv(path)

def process(cleanFraudByPaymentMethod) -> pd.DataFrame:
    import pandas as pd

    total_millions = float(cleanFraudByPaymentMethod['lossMillions'].sum())
    return pd.DataFrame([{
        'totalLossMillions': total_millions,
        'totalLossMillionsInt': int(round(total_millions))
    }])
